#include <vector>
#include <bitset>
#include <algorithm>

using namespace std;

class Solution {
public:
    int minZeroArray(vector<int>& nums, vector<vector<int>>& queries) {
        if (all_of(nums.begin(), nums.end(), [](int x) { return x == 0; })) {
            return 0;
        }

        int n = nums.size();
        vector<bitset<1001>> masks(n);
        for (int i = 0; i < n; ++i) {
            masks[i].set(0);
        }

        for (int k = 0; k < (int)queries.size(); ++k) {
            int l = queries[k][0];
            int r = queries[k][1];
            int val = queries[k][2];

            for (int i = l; i <= r; ++i) {
                masks[i] |= (masks[i] << val);
            }

            bool allReached = true;
            for (int i = 0; i < n; ++i) {
                if (nums[i] > 1000 || !masks[i].test(nums[i])) {
                    allReached = false;
                    break;
                }
            }
            if (allReached) return k + 1;
        }

        return -1;
    }
};

import java.util.*;

class Solution {
    public int minZeroArray(int[] nums, int[][] queries) {
        boolean allZero = true;
        for (int x : nums) {
            if (x != 0) {
                allZero = false;
                break;
            }
        }
        if (allZero) return 0;

        int n = nums.length;
        BitSet[] masks = new BitSet[n];
        for (int i = 0; i < n; i++) {
            masks[i] = new BitSet(1005);
            masks[i].set(0);
        }

        for (int k = 0; k < queries.length; k++) {
            int l = queries[k][0];
            int r = queries[k][1];
            int val = queries[k][2];

            for (int i = l; i <= r; i++) {
                BitSet next = new BitSet(1005);
                for (int b = masks[i].nextSetBit(0); b >= 0 && b + val <= 1000; b = masks[i].nextSetBit(b + 1)) {
                    next.set(b + val);
                }
                masks[i].or(next);
            }

            boolean allReached = true;
            for (int i = 0; i < n; i++) {
                if (!masks[i].get(nums[i])) {
                    allReached = false;
                    break;
                }
            }
            if (allReached) return k + 1;
        }

        return -1;
    }
}

var minZeroArray = function(nums, queries) {
    if (nums.every(x => x === 0)) return 0;

    const n = nums.length;
    const masks = new Array(n).fill(1n);

    for (let k = 0; k < queries.length; k++) {
        const [l, r, val] = queries[k];
        const shift = BigInt(val);

        for (let i = l; i <= r; i++) {
            masks[i] |= (masks[i] << shift);
        }

        let allReached = true;
        for (let i = 0; i < n; i++) {
            const target = BigInt(nums[i]);
            if (!((masks[i] >> target) & 1n)) {
                allReached = false;
                break;
            }
        }
        if (allReached) return k + 1;
    }

    return -1;
};
